use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Body {
    Text { text: String },
    File { file_id: String },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SendMessage {
    /// UUID generated by the sender; keep it unchanged on retry.
    pub id: String,
    pub to: String,
    pub body: Body,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Message {
    pub id: String,
    pub from: String,
    pub to: String,
    pub body: Body,
    pub created_at: i64,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ClientEvent {
    Send {
        message: SendMessage,
    },
    /// Recipient acknowledges a message; sender acknowledges a delivered event.
    Ack {
        id: String,
    },
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ServerEvent {
    Ready { device_id: String },
    Accepted { id: String },
    Message { message: Message },
    Delivered { id: String },
    Error { code: u16, message: String },
}

#[derive(Debug, Serialize, Deserialize)]
pub struct FileInfo {
    pub id: String,
    pub name: String,
    pub size: u64,
    pub sha256: String,
    pub expires_at: i64,
}
